/** autogenerated **/
Ext._define('common.official_journal.document.Manage', {
    extend: 'toolkit.widget.TabPanel',


    getDocumentBoxTilePanel: function() {
        if (!this._mainBoxTilePanel) {
            this._mainBoxTilePanel = Ext._create('core.TilePagePanel', {
                region: 'center',
            });
        }

        return this._mainBoxTilePanel;
    },


    getDocumentGrid: function() {
        if(!this._grid) {
            this._grid = Ext._create('common.official_journal.document.Grid', {
                region: 'west',
                gridAutoLoad: true,
                width: '45%',
                split: true,
                items: [
                    this.getDocumentBoxTilePanel(),
                ]
            });
            this._grid.getSelectionModel().on({
                scope: this,
                rowselect: function(grid, index, record) {
                    // console.log(record.data)
                    this.readView(record.get('pk'));
                }
            });
        }

        return this._grid;
    },

    readView: function(pk) {
        var mask = new Ext.LoadMask(this.getDocumentBoxTilePanel().getEl(), {msg: 'Carregando informações...'});

        mask.show();

        this.getDocumentBoxTilePanel().setPageContent('');

        Ext.Ajax.request({
            url: core.callAction('JournalDocument', 'renderer_document'),
            scope: this,
            autoAbort: true,
            params: {
                idDocument: pk
            },
            callback: function() {
                mask.hide();
            },
            success: function(xhr) {
                var rst = Ext.decode(xhr.responseText);
                if(rst.success) {
                    this.getDocumentBoxTilePanel().setPageContent(rst.content);
                }
                else
                    Ext.Msg.show({
                        title: 'Carregando informações',
                        msg: rst.message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
            },
            failure: function() {
                Ext.Msg.show({
                    title: 'Carregando informações',
                    msg: 'Recurso indisponivel no momento.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        });
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Documentos do DOE'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getDocumentBoxTilePanel(),
                    this.getDocumentGrid()
                ]
            }
        );

        common.official_journal.document.Manage.superclass.constructor.call(this, cfg);
    }
});

